<script module lang="ts">
/**
 * Picks several values from a filterable closed list (`design/components/multi-select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/multi-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/combobox'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  afterRender,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { useListPresence, usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/multi-select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import MultiSelectChip from './MultiSelectChip.svelte'
import Skeleton from '../structure/Skeleton.svelte'

export interface MultiSelectOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface MultiSelectMessages {
  add?: (text: string) => string
  added?: (value: string, count: number) => string
  removed?: (label: string, count: number) => string
  refused?: (text: string) => string
  alreadySelected?: (value: string) => string
  selected?: (count: number, max: number | undefined) => string
  showOptions?: string
  remove?: (label: string) => string
  loadingOptions?: string
  options?: (count: number) => string
}

export interface MultiSelectProps {
  /**
   * Allows values outside `options` (the spec's boundary with TagInput). Typed text that matches
   * no option and passes `validate` appears as an extra last row, `Add "{text}"`, and choosing
   * it adds a chip. The row is removed, not disabled, when the text is empty or rejected,
   * matches an option, is already selected, or the field is full.
   */
  allowCustom?: boolean
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The initial filter text, for galleries and tests, like `defaultOpen`. The spec's States
   * table includes "open filtered", and a fixture cannot type.
   */
  defaultInputValue?: string
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string[]
  disabled?: boolean
  /**
   * The empty-results text, passed in so apps can localize it (as in Combobox).
   */
  emptyMessage?: string
  /**
   * `true` filters with the locale-aware contains check (`useFilter`, based on Intl), as in
   * Combobox. `false` means **the app filtered** (async), so server results are not filtered
   * again. The mint row is never filtered out, because it is built from the text.
   */
  filter?: boolean
  id?: string
  /**
   * The controlled filter text, which async apps use to run their queries (as in Combobox). It
   * is implemented here by hand because this member uses the lower-level collection hooks.
   */
  inputValue?: string
  invalid?: boolean
  /**
   * Async loading, as in Combobox, with the same loading and empty recipes.
   */
  loading?: boolean
  /**
   * The maximum number of values, with TagInput's at-max rule. At the maximum the input becomes
   * read-only but stays focusable, labelled and announced as read-only. Backspace still removes
   * the last chip, and chips stay removable. Unchecked options are disabled. Checked options
   * stay active.
   */
  max?: number
  /**
   * The member's strings. See `MultiSelectMessages`.
   */
  messages?: MultiSelectMessages
  /**
   * Serializes as in TagInput: a comma-joined hidden input, disabled with the field.
   */
  name?: string
  /**
   * Fires when focus leaves the whole field, for touched validation (as in TagInput). Chips,
   * input and chevron are one control, so moving focus between them is not a blur.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (values: string[]) => void
  onInputChange?: (value: string) => void
  /**
   * Paging, as in Combobox. Fires when the highlight reaches the last real row or the open
   * listbox scrolls to its end, while `loading` is false, at most once per `options` length. The
   * app then appends the next page and sets `loading`. The highlight trigger is the primary one
   * (WCAG 2.1.1), because keyboard users cannot reach a scroll edge when the page fits the
   * panel. The mint row does not count as the last real row.
   */
  onLoadMore?: () => void
  /**
   * The current list, shaped as in Combobox. With async loading the app supplies it per query.
   */
  options: MultiSelectOption[]
  /**
   * Shown only while there are no chips, because the chips are the value (as in TagInput).
   */
  placeholder?: string
  /**
   * As in Combobox (`combobox.md`; the conventions' sheet presentation). `'auto'` shows the
   * popup as a sheet below `30rem`, and `'popover'` keeps the popper at every width. There is no
   * always-sheet option.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalizes or rejects custom text, as in TagInput. Return the normalized value, or `null` to
   * reject it, which hides the mint row. Options chosen from the list skip it.
   */
  validate?: (raw: string) => string | null
  /**
   * **Always in options order**: the reported array and the chips follow `options`, not click
   * order. A selection is a set, so the same choices always give the same value.
   */
  value?: string[]
}
</script>

<script lang="ts">
let {
  allowCustom = false,
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultInputValue,
  defaultOpen,
  defaultValue,
  disabled = false,
  emptyMessage = 'No results',
  filter = true,
  id: idOwn,
  inputValue,
  invalid: invalidOwn = false,
  loading = false,
  max,
  messages,
  name,
  onBlur,
  onChange,
  onInputChange,
  onLoadMore,
  options,
  placeholder,
  presentation = 'auto',
  size = 'md',
  validate,
  value,
}: MultiSelectProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let uncontrolled = $state(defaultValue ?? [])
// svelte-ignore state_referenced_locally
let uncontrolledText = $state(defaultInputValue ?? '')
let refused = $state(false)
let announcement = $state('')
let loadMoreAt = $state(-1)
let settled = $state(false)
let chipList = $state<HTMLElement | null>(null)
let frame = $state<HTMLElement | null>(null)
let list = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
let textField = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const values = $derived(value ?? uncontrolled)
const text = $derived(inputValue ?? uncontrolledText)
const sheeting = $derived(presentation === 'auto' && phone.current)
const say = $derived({
  add: (text: string) => `Add "${text}"`,
  added: (value: string, count: number) => `${value} added, ${count} selected`,
  removed: (label: string, count: number) => `${label} removed, ${count} selected`,
  refused: (text: string) => `Cannot add "${text}"`,
  alreadySelected: (value: string) => `"${value}" is already selected`,
  selected: (count: number, max: number | undefined) =>
    max !== undefined && count >= max ? `Maximum of ${max} selected` : `${count} selected`,
  showOptions: 'Show options',
  remove: (label: string) => `Remove ${label}`,
  loadingOptions: 'Loading options…',
  options: (count: number) => `${count} options`,
  ...messages,
})
const atMax = $derived(max !== undefined && values.length >= max)
const countId = $derived(`${uid}-count`)
const labels = $derived(new Map(options.map((option) => [option.value, option.label] as const)))
const labelOf = $derived((entry: string) => labels.get(entry) ?? entry)
const ordered = $derived((chosen: ReadonlySet<string>) => [
  ...options.filter((option) => chosen.has(option.value)).map((option) => option.value),
  ...[...chosen].filter((entry) => !options.some((option) => option.value === entry)),
])
const orderedValues = $derived(ordered(new Set(values)))
const collator = $derived(new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }))
const contains = $derived((haystack: string, needle: string) => {
  const hay = haystack.normalize('NFC')
  const pin = needle.normalize('NFC')
  for (let from = 0; from + pin.length <= hay.length; from += 1) {
    if (collator.compare(hay.slice(from, from + pin.length), pin) === 0) return true
  }
  return pin === ''
})
const sameText = $derived(
  (a: string, b: string) => collator.compare(a.normalize('NFC'), b.normalize('NFC')) === 0,
)
const shown = $derived(
  filter && text !== '' ? options.filter((option) => contains(option.label, text)) : options,
)
const normalized = $derived(
  allowCustom && !atMax
    ? (validate ?? ((raw: string) => (raw.trim() === '' ? null : raw.trim())))(text)
    : null,
)
const mint = $derived(
  (() => {
    const candidate = normalized
    if (candidate === null || values.includes(candidate)) return null
    return options.some((option) => option.value === candidate || sameText(option.label, candidate))
      ? null
      : candidate
  })(),
)
const rows = $derived(
  (mint === null
    ? shown
    : [...shown, { value: mint, label: say.add(mint) }]) as MultiSelectOption[],
)
const isOff = $derived(
  (row: MultiSelectOption) => row.disabled === true || (atMax && !values.includes(row.value)),
)
const navigable = $derived(rows.filter((row) => !isOff(row)).map((row) => row.value))
const lastReal = $derived(navigable.filter((key) => key !== mint).at(-1))
const commit = $derived((next: string[]) => {
  uncontrolled = next
  onChange?.(next)
})
const commitText = $derived((next: string) => {
  uncontrolledText = next
  onInputChange?.(next)
})
const pick = $derived((chosen: string[]) => {
  const before = values
  const minted = mint
  const next = ordered(new Set(chosen))
  const dropped = before.filter((entry) => !next.includes(entry))
  commit(next)
  if (minted !== null && next.includes(minted) && !before.includes(minted)) {
    commitText('')
    announcement = say.added(minted, next.length)
    return
  }
  if (dropped.length > 0 && next.length < before.length) {
    announcement = say.removed(labelOf(dropped[0] ?? ''), next.length)
  }
})
const requestMore = $derived(
  () =>
    !loading &&
    loadMoreAt !== options.length &&
    ((loadMoreAt = options.length), onLoadMore?.(), true),
)
const removeButton = $derived(
  (at: number) =>
    chipList?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[at] ?? null,
)
const documentDirection = useDirection(() => frame)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      collection: zag.collection({
        items: rows,
        itemToValue: (item) => item.value,
        itemToString: (item) => item.label,
        isItemDisabled: (item) => isOff(item),
      }),
      multiple: true,
      value: values,
      inputValue: text,
      defaultOpen: defaultOpen,
      disabled: disabled,
      closeOnSelect: false,
      selectionBehavior: 'preserve' as const,
      allowCustomValue: true,
      positioning: { placement: 'bottom-start' as const, gutter: 2, sameWidth: false },
      ids: {
        ...(id === undefined ? {} : { input: id }),
        item: (key: string) => `${uid}-opt-${rows.findIndex((row) => row.value === key)}`,
      },
      onInteractOutside: (event) =>
        ((target) =>
          (frame?.contains(target) || panel?.contains(target)) && event.preventDefault())(
          event.detail.originalEvent.target as Node | null,
        ),
      onValueChange: (details) => {
        pick(details.value)
      },
      onInputValueChange: (details) => {
        commitText(details.inputValue)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const status = $derived(
  !api.open
    ? ''
    : loading
      ? say.loadingOptions
      : rows.length === 0
        ? emptyMessage
        : say.options(rows.length),
)
const showEmpty = $derived(api.open && !loading && rows.length === 0)
const aimFirst = $derived(() =>
  navigable[0] === undefined ? api.clearHighlightValue() : api.setHighlightValue(navigable[0]),
)
const remove = $derived((entry: string) => {
  const before = orderedValues
  const at = before.indexOf(entry)
  const target = at === -1 || at + 1 >= before.length ? null : removeButton(at + 1)
  const next = before.filter((held) => held !== entry)
  commit(next)
  announcement = say.removed(labelOf(entry), next.length)
  if (target) target.focus()
  else api.focus()
})
const typed = $derived((event: Event) => {
  const input = event.target as HTMLInputElement
  const typedText = input.value
  const start = input.selectionStart
  const end = input.selectionEnd
  commitText(typedText)
  if (!api.open) api.setOpen(true)
  afterRender(() => {
    if (input.value !== text) {
      input.value = text
      return
    }
    queueMicrotask(() => {
      if (start === null || end === null || input.value !== typedText) return
      if (input.ownerDocument.activeElement === input) input.setSelectionRange(start, end)
    })
  })
})
const fieldKeyDown = $derived((event: KeyboardEvent) => {
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    event.preventDefault()
    const down = event.key === 'ArrowDown'
    const from =
      api.open && api.highlightedValue !== null ? navigable.indexOf(api.highlightedValue) : -1
    const target =
      from === -1
        ? down
          ? navigable[0]
          : navigable[navigable.length - 1]
        : navigable[from + (down ? 1 : -1)]
    if (!api.open) api.setOpen(true)
    if (target !== undefined) api.setHighlightValue(target)
    return
  }
  if (event.key === 'Enter') {
    if (!api.open) return
    event.preventDefault()
    const highlighted = api.highlightedValue
    if (highlighted !== null) {
      if (navigable.includes(highlighted)) api.selectValue(highlighted)
      return
    }
    if (allowCustom && text.trim() !== '') {
      refused = true
      announcement =
        normalized !== null && values.includes(normalized)
          ? say.alreadySelected(normalized)
          : say.refused(text.trim())
    }
    return
  }
  if (event.key === 'Escape') {
    if (api.open) {
      event.preventDefault()
      api.setOpen(false)
      return
    }
    if (text !== '') {
      event.preventDefault()
      commitText('')
    }
    return
  }
  if (event.key === 'Backspace' && text === '') {
    const last = orderedValues[orderedValues.length - 1]
    if (last !== undefined) remove(last)
    return
  }
  if (event.key === 'ArrowLeft' && (event.target as HTMLInputElement).selectionStart === 0) {
    removeButton(orderedValues.length - 1)?.focus()
  }
})
const chipKeyDown = $derived((event: KeyboardEvent, entry: string) => {
  const at = orderedValues.indexOf(entry)
  if (at === -1) return
  if (event.key === 'Backspace' || event.key === 'Delete') {
    event.preventDefault()
    remove(entry)
    return
  }
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault()
    const step = event.key === 'ArrowLeft' ? -1 : 1
    if (at + step === orderedValues.length) api.focus()
    else if (at + step >= 0) removeButton(at + step)?.focus()
  }
})
const toggle = $derived(() => {
  if (disabled) return
  api.setOpen(!api.open)
  api.focus()
})
const pressField = $derived((event: MouseEvent) => {
  if ((event.target as HTMLElement).closest('button, input')) return
  event.preventDefault()
  api.focus()
})
const leave = $derived((event: FocusEvent) => {
  const landed = event.relatedTarget as Node | null
  if ((event.currentTarget as HTMLElement).contains(landed)) return
  if (landed !== null && panel?.contains(landed)) return
  if (api.open)
    service.send({ type: 'LAYER.INTERACT_OUTSIDE', src: 'interact-outside', restoreFocus: false })
  onBlur?.(event)
})
const chips = useListPresence(
  () => orderedValues,
  (entry: string) => entry,
)
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  settled = true
}
watchEffect(effect1)
const effect2 = () => {
  api.open && aimFirst()
}
watchEffect(effect2, { watch: () => text })
const effect3 = () => {
  api.open && api.highlightedValue === null && aimFirst()
}
watchEffect(effect3, { watch: () => api.open, mount: false })
const effect4 = () => {
  api.open && api.highlightedValue !== null && api.highlightedValue === lastReal && requestMore()
}
watchEffect(effect4, { watch: () => api.highlightedValue })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'MultiSelect',
    element: () => textField,
    state: () => ({
      value: orderedValues,
      options: [
        ...options.map((option) => ({
          id: option.value,
          label: option.label,
          ...(option.disabled === true || (atMax && !values.includes(option.value))
            ? { disabled: true }
            : {}),
        })),
        ...orderedValues
          .filter((entry) => !labels.has(entry))
          .map((entry) => ({ id: entry, label: entry })),
      ],
      'input-value': text,
      open: api.open,
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      choose: {
        argument: 'ids',
        run: (value) =>
          (() => {
            const next = ordered(new Set(value))
            if (max !== undefined && next.length > max)
              throw new Error(`The field holds at most ${max} values.`)
            if (
              next.length === orderedValues.length &&
              next.every((entry, at) => entry === orderedValues[at])
            )
              return
            commit(next)
          })(),
      },
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (atMax) throw new Error('The field is full, so its text is read-only.')
            commitText(value)
          })(),
      },
      open: () => api.setOpen(true),
      close: () => api.setOpen(false),
    },
  })
  release5 = () => {
    ran()
  }
}
watchEffect(effect5)
onDestroy(() => release5?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={frame}
    class={styles.field}
    id={api.getControlProps().id}
    data-size={size}
    data-state={api.open ? 'open' : 'closed'}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-loading={(loading) ? '' : undefined}
    data-refused={(refused) ? '' : undefined}
    data-at-max={(atMax) ? '' : undefined}
    data-sheeting={(sheeting && api.open) ? '' : undefined}
    data-member="multi-select"
    onmousedown={(event) => { pressField(event) }}
    onfocusout={(event) => { leave(event) }}
    onanimationend={(event) => { if (event.animationName.includes('refusal')) (refused = false) }}
    ><ul bind:this={chipList} class={styles.chips}
      >{#each chips.current as chip (chip.key)
        }<MultiSelectChip
          label={labelOf(chip.item)}
          open={chip.open}
          appear={settled}
          {disabled}
          removeLabel={say.remove(labelOf(chip.item))}
          onRemove={() => { remove(chip.item) }}
          onKeyDown={(event) => { chipKeyDown(event, chip.item) }}
          onDone={() => { chip.done() }}
      />{/each
    }</ul
    ><input
      bind:this={textField}
      {...attributes({ ...api.getInputProps(), onKeydown: fieldKeyDown, onInput: typed })}
      class={styles.input}
      placeholder={values.length === 0 ? placeholder : undefined}
      readonly={atMax}
      aria-controls={(api.open) ? api.getContentProps().id : undefined}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={[ariaDescribedby, countId].filter(Boolean).join(' ')}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
    /><button
      {...attributes(mergeParts({ ...api.getTriggerProps(), onClick: undefined, onPointerdown: undefined }, { onMousedown: (event: MouseEvent) => { (event.preventDefault(), toggle()) }, onClick: (event: MouseEvent) => { if (event.detail === 0) toggle() } }))}
      class={styles.chevron}
      aria-label={say.showOptions}
      >{#if loading
        }<span class={styles.spinner}><Icon name="loading" {size} /></span
      >{:else
        }<Icon name="expand" {size}
      />{/if
    }</button
    ><span class={styles.reader} id={countId}>{say.selected(values.length, max)}</span
    ><span class={styles.reader} aria-live="polite">{announcement}</span
    ><div class={styles.status} role="status" aria-live="polite">{status}</div
    >{#if name !== undefined
      }<input type="hidden" {name} value={orderedValues.join(',')} {disabled}
    />{/if
  }</div
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          class={styles.content}
          style:--radix-popover-trigger-width={'var(--reference-width)'}
          style:--radix-popover-content-available-height={'var(--available-height)'}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          data-size={size}
          data-state={api.open ? 'open' : 'closed'}
          data-member="multi-select"
          ><ul
            bind:this={list}
            {...attributes(mergeParts(api.getContentProps(), { onScroll: () => { (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 && requestMore() } }))}
            class={styles.listbox}
            hidden={undefined}
            aria-label={ariaLabelledby === undefined ? ariaLabel : undefined}
            aria-labelledby={ariaLabelledby}
            >{#each rows as row, at (row.value)
              }<li
                {...attributes(api.getItemProps({ item: row }))}
                class={styles.option}
                aria-selected={values.includes(row.value) ? 'true' : 'false'}
                aria-labelledby={`${uid}-opt-${at}` + '-label'}
                aria-describedby={(row.description !== undefined) ? `${uid}-opt-${at}` + '-description' : undefined}
                data-mint={(row.value === mint) ? '' : undefined}
                ><span class={styles.check}
                  >{#if row.value === mint
                    }<Icon name="add" size="sm"
                  />{:else if values.includes(row.value)
                    }<Icon name="confirm" size="sm"
                  />{/if
                }</span
                ><span class={styles.text}
                  ><span class={styles.optionLabel} id={`${uid}-opt-${at}` + '-label'}
                    >{row.label
                  }</span
                  >{#if row.description !== undefined
                    }<span class={styles.description} id={`${uid}-opt-${at}` + '-description'}
                      >{row.description
                    }</span
                  >{/if
                }</span
              ></li
            >{/each
          }</ul
          >{#if loading
            }<div class={styles.rows} aria-hidden="true"
              >{#each [0, 1, 2] as row (row)
                }<div class={styles.row}><Skeleton textStep="sm" /></div
              >{/each
            }</div
          >{/if
          }{#if showEmpty}<div class={styles.empty} aria-hidden="true">{emptyMessage}</div>{/if
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          ><div
            bind:this={panel}
            class={styles.sheetBody}
            data-size={size}
            data-member="multi-select"
            ><ul
              bind:this={list}
              {...attributes(mergeParts(api.getContentProps(), { onScroll: () => { (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 && requestMore() } }))}
              class={styles.listbox}
              hidden={undefined}
              aria-label={ariaLabelledby === undefined ? ariaLabel : undefined}
              aria-labelledby={ariaLabelledby}
              >{#each rows as row, at (row.value)
                }<li
                  {...attributes(api.getItemProps({ item: row }))}
                  class={styles.option}
                  aria-selected={values.includes(row.value) ? 'true' : 'false'}
                  aria-labelledby={`${uid}-opt-${at}` + '-label'}
                  aria-describedby={(row.description !== undefined) ? `${uid}-opt-${at}` + '-description' : undefined}
                  data-mint={(row.value === mint) ? '' : undefined}
                  ><span class={styles.check}
                    >{#if row.value === mint
                      }<Icon name="add" size="sm"
                    />{:else if values.includes(row.value)
                      }<Icon name="confirm" size="sm"
                    />{/if
                  }</span
                  ><span class={styles.text}
                    ><span class={styles.optionLabel} id={`${uid}-opt-${at}` + '-label'}
                      >{row.label
                    }</span
                    >{#if row.description !== undefined
                      }<span class={styles.description} id={`${uid}-opt-${at}` + '-description'}
                        >{row.description
                      }</span
                    >{/if
                  }</span
                ></li
              >{/each
            }</ul
            >{#if loading
              }<div class={styles.rows} aria-hidden="true"
                >{#each [0, 1, 2] as row (row)
                  }<div class={styles.row}><Skeleton textStep="sm" /></div
                >{/each
              }</div
            >{/if
            }{#if showEmpty}<div class={styles.empty} aria-hidden="true">{emptyMessage}</div>{/if
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
